class.description:
A lobby directory is a [NetwService] that implements [method _host_lobby], [method _join_lobby], [method _list_lobbies] and [method _leave_lobby]. Its lobbies appear in [NetwConnection] like any other server.
[codeblock]
extends LobbyDirectory

func _init() -> void:
    display_name = "Rooms"
    address_label = "Room ID"
    capabilities = CAPABILITY_BROWSE

func _peer_class() -> StringName:
    return &"RoomMultiplayerPeer"

func _host_lobby(settings: Dictionary) -> void:
    var room := await Rooms.open(settings.get("name", "room"))
    if room == null:
        fail(ERR_CANT_CREATE, "the room service rejected the lobby")
        return
    deliver(room.peer())

func _join_lobby(address: String) -> void:
    var room := await Rooms.join(address)
    deliver(room.peer()) if room else fail(ERR_CANT_CONNECT, "no such room")

func _list_lobbies() -> void:
    var addresses := PackedStringArray()
    var names := PackedStringArray()
    var infos: Array[NetwServerInfo] = []
    for room in await Rooms.list():
        addresses.append(room.id)
        names.append(room.title)
        infos.append(room.info())
    publish_lobbies(addresses, names, infos)

func _leave_lobby() -> void:
    Rooms.leave()
[/codeblock]
A directory whose peer class already has a transport only lists lobbies, and joining one goes through that transport. [WebTorrentLobbyDirectory] and [LANLobbyDirectory] work this way.
